    whatIs: 'Was sind programmatische Tool-Aufrufe?',
    whatIsDesc: 'Programmatische Tool-Aufrufe ermöglichen es einem KI-Agenten, Code zu schreiben, der Tools in einer Sandbox-Umgebung aufruft — anstatt für jeden Tool-Aufruf einen separaten Modell-Roundtrip zu benötigen. Der Agent schreibt ein Skript, die Laufzeitumgebung führt es aus, und Tool-Aufrufe erfolgen direkt aus dem Code. Nur das Endergebnis wird in das Kontextfenster des Modells zurückgegeben.',
