  chatCompaction: {
    title: 'Chat Compaction',
    description: 'Wie man lange Agent-Chats verdichtet, ohne die Fähigkeit zur Wiederaufnahme, zum Retrieval und zur Rekonstruktion exakter Details zu verlieren.',
    whatIs: 'Was ist Chat Compaction?',
    whatIsDesc: 'Chat Compaction ist die gezielte Verdichtung langer Agent-Gespräche in kleinere, strukturierte Repräsentationen. Es geht nicht nur darum, mehr Text in ein Kontextfenster zu pressen. Das eigentliche Ziel ist, alte Arbeit wiederauffindbar zu halten, damit ein Agent später an derselben Aufgabe weiterarbeiten kann, ohne jeden Roh-Turn erneut lesen zu müssen.',
    quote: 'Compaction ist Navigation, nicht Wahrheit.',
    why: 'Warum Agenten das brauchen',
    activeTitle: 'Aktive Sessions',
    activeDesc: 'Lang laufende Agenten sammeln User-Turns, Tool-Calls, Ergebnisse, Retries und Zwischenstände an. Wenn nichts kompakt wird, läuft das Kontextfenster voll und der Agent verliert entweder nützlichen frischen Zustand oder zahlt immer mehr, um alles mitzuschleppen.',
    inactiveTitle: 'Inaktive Sessions',
    inactiveDesc: 'Alte Sessions fallen oft komplett aus dem heißen Cache. Compaction erzeugt eine wiederaufnehmbare Form kalter Historie, sodass ein Agent mit Summary plus gezieltem Recall neu ansetzen kann, statt den ganzen Thread zu rehydrieren.',
    blocks: 'Die vier Kernbausteine',
    compress: 'Verdichten',
    compressDesc: 'Ältere Turns werden in Summaries überführt, sobald sie nicht mehr im heißen Kontextfenster leben müssen.',
    structure: 'Strukturieren',
    structureDesc: 'Kompaktierte Historie wird in verlinkten Blöcken oder Hierarchien gespeichert, damit alte Arbeit navigierbar bleibt statt zu einem Blob zu werden.',
    retrieve: 'Wiederfinden',
    retrieveDesc: 'Nur die relevanten kompaktierten Fragmente werden zurückgeholt, wenn die aktuelle Aufgabe von früheren Entscheidungen oder Fakten abhängt.',
    expand: 'Expandieren',
    expandDesc: 'Exakte Formulierungen, Werte und Kausalketten werden bei Bedarf zurückgeholt, statt sie aus Summaries zu erraten.',
    pattern: 'Das Kernmuster',
    interactive: 'Interaktiver Compaction Explorer',
    interactiveDesc: 'Vergleiche überladene Live-Sessions mit alten inaktiven Sessions, die später wieder aufgenommen werden müssen.',
    breaks: 'Was naive Compaction kaputt macht',
    breaksDesc: 'Naive Truncation wirft alten Kontext komplett weg. Naive Summaries behalten nur eine plausible Paraphrase. Beide Ansätze scheitern auf dieselbe Weise: Alte Arbeit wird billiger mitzuschleppen, aber schwerer zu vertrauen.',
    break1: 'Wichtige Entscheidungen verlieren ihre Begründung.',
    break2: 'Offene Loops verschwinden, sodass der Agent vergisst, was noch ungelöst war.',
    break3: 'Exakte Commands, Pfade, Timestamps und Werte verschwimmen in Summary-Sprache.',
    break4: 'Alte Summaries können neuerer Evidenz widersprechen, wenn man sie wie Ground Truth behandelt.',
    practice: 'Gute Compaction in der Praxis',
    rules: 'Designregeln',
    rule1: 'Halte einen frischen Tail für aktive Arbeit.',
    rule2: 'Verdichte alte Turns in strukturierte, abfragbare Einheiten.',
    rule3: 'Nutze Retrieval für Relevanz, Expansion für Präzision.',
    rule4: 'Lass neue Evidenz alte Summaries übersteuern.',
    separation: 'Saubere Trennung der Ebenen',
    separation1: 'Frischer Kontext ist für unmittelbares Reasoning da.',
    separation2: 'Kompaktierte Historie ist für Navigation und Wiederaufnahme da.',
    separation3: 'Expansion ist für exakte Fakten und Kausalität da.',
    separation4: 'Langzeit-Memory speichert destillierte Fakten, nicht jeden Turn.',
    keyTakeaways: 'Wichtige Erkenntnisse',
    takeaway1: 'Compaction spart nicht nur Tokens, sondern erhält Wiederauffindbarkeit.',
    takeaway2: 'Gute Compaction hilft sowohl bei überladenen Live-Sessions als auch bei alten Sessions, die nicht mehr gecached sind.',
    takeaway3: 'Summaries sind Recall-Hilfen, keine Beweise. Exakte Claims sollten aus gezielter Expansion kommen.',
    takeaway4: 'Die besten Systeme trennen frischen Kontext, kompaktierte Historie, Retrieval und Langzeit-Memory sauber voneinander.',
  },

