    underTheHoodDesc: 'System-Prompts sind keine Magie — sie sind Teil des gleichen Nachrichtenarrays, das bei jedem API-Call an das Modell gesendet wird. Die Mechanik zu verstehen hilft beim Schreiben besserer Prompts.',
    specialTokens: 'Special Tokens & Rollen',
    specialTokensDesc: "Rollen und Chat-Templates hängen von API und Modell ab. Manche APIs haben developer- und tool-Rollen oder separate Toolergebnisse zusätzlich zu Nutzer- und Assistentennachrichten. Nutze das Anbieterschema und übernimm keine Spezialtokens einer fremden Modellfamilie.",
    primacyBias: "Instruktionspriorität und Position",
    primacyBiasDesc: "Training und Rollensemantik legen die vorgesehene Instruktionspriorität fest. Positionseffekte in langen Kontexten sind ein separates empirisches Phänomen; die erste Textposition verleiht allein weder Autorität noch garantiert sie Befolgung.",
    stateless: 'Zustandslos by Design',
    statelessDesc: "Das Modell nutzt den für die aktuelle Inferenz bereitgestellten Kontext. Der Host kann Nachrichten erneut senden oder serverseitigen Gesprächszustand verwalten. Tokenabrechnung und Caching hängen von der API ab; ein gespeichertes Gespräch aktualisiert keine Modellgewichte.",
