    whatIsDesc: "Knowledge Distillation trainiert einen Student darauf, nützliches Verhalten eines Teachers nachzubilden. Die Lernsignale können erzeugte Texte, weiche Ausgabeverteilungen oder Zwischenmerkmale sein. Ein kleinerer Student kann günstiger auszuführen sein; Qualität und Kompression hängen von Modell, Daten und Aufgabe ab.",
    analogy: '\u201EStell dir einen Meisterkoch vor, der einem Lehrling beibringt \u2013 nicht nur die Rezepte, sondern all die subtilen Intuitionen: warum dieses Gew\u00FCrz fast passt, warum diese Technik nah dran, aber nicht ganz richtig ist.\u201C',
