    hitStep2: 'Cache gefunden! KV-Paare laden',
    hitStep3: 'Nur NEUE Tokens verarbeiten',
    hitResult: "Gecachter Prefix wird wiederverwendet; der Suffix wird weiter verarbeitet",
    howItWorks: 'Wie Anbieter es implementieren',
    howItWorksDesc: 'Jeder große LLM-Anbieter hat seinen eigenen Ansatz für Prompt Caching, mit unterschiedlichen Kompromissen bei Kontrolle, Preisgestaltung und minimaler Token-Anzahl.',
