    anthropicDesc: "Cache-Verhalten, minimale Prefixlänge, Write- und Read-Preis sowie Lebensdauer hängen von Claude-Modell und Cache-Modus ab. Prüfe cache_creation_input_tokens und cache_read_input_tokens. Ein kalter Write und ein warmer Read kosten unterschiedlich viel.",
