    // Page content
    coreIdeaTag: 'Die Kernidee',
    coreIdeaTitle: 'Prompt-Caching belohnt stabile Präfixe.',
    coreIdeaDesc: 'Prompt-Caching ist kein Gedächtnis, kein Retrieval und keine Datenbank. Es ist ein Weg für einen Inferenz-Anbieter, den bereits berechneten KV-Zustand für den Anfang eines Prompts wiederzuverwenden, wenn spätere Anfragen mit denselben Tokens beginnen. Der veränderliche Teil muss weiterhin verarbeitet werden; der Gewinn entsteht dadurch, dass das wiederholte Präfix nicht neu berechnet wird.',
    prefixContractTitle: 'Das Präfix ist der Vertrag',
    prefixContractDesc: 'Ob etwas cachebar ist, entscheidet sich größtenteils, bevor das Modell die eigentliche Aufgabe sieht. Wenn der lange, teure Teil bei Token 500 beginnt, sich aber Token 20 bei jeder Anfrage ändert, ist das gemeinsame Präfix faktisch zerstört. Entwirf zuerst die Prompt-Struktur und justiere danach die Anbieter-Einstellungen.',
    hitVsMissTitle: 'Cache-Hit versus Cache-Miss',
    hitVsMissDesc: 'Bei einem Miss führt der Anbieter das teure Prefill für den gesamten Prompt aus und schreibt gegebenenfalls das wiederverwendbare Präfix. Bei einem Hit liest der Anbieter das gecachte Präfix und berechnet nur das Suffix. Das verändert Eingabekosten und Latenz, aber die Ausgabegenerierung kostet weiterhin, was sie kostet.',
    tryPrefixTitle: 'Probiere die Präfix-Regel aus',
    tryPrefixDesc: 'Der schnellste Weg, Prompt-Caching zu verstehen, ist, den Anfang eines Prompts zu bearbeiten. Winzige Änderungen ganz oben können den Cache-Hit zerstören; Änderungen nach dem stabilen Präfix erhalten ihn meist.',
    providerDiffTitle: 'Anbieter verhalten sich unterschiedlich',
    providerDiffDesc: 'Baue deine Architektur nicht um eine einzelne Marketing-Zahl herum. Anbieter unterscheiden sich darin, wie Caches erstellt werden, wie lange sie leben, welche Eingaben zählen und wie die Nutzung gemeldet wird. Die übertragbare Fähigkeit ist Prompt-Disziplin: stabiles Präfix zuerst, volatiles Suffix zuletzt, jedes Deployment messen.',
    tableHowToThink: 'Wie man es einordnet',
    tableWhatToVerify: 'Was zu prüfen ist',
    useWhenTitle: 'Nutze es, wenn',
    avoidWhenTitle: 'Erwarte keine Gewinne, wenn',
    costModelTitle: 'Kostenmodell',
    costModelDesc: "Writes und Reads können unterschiedliche Preise haben. Die Ersparnis hängt von Wiederverwendung vor Ablauf ab. Der Rechner zeigt diese Gruppierung ausdrücklich. Ersetze seinen hypothetischen Tarif durch die Preise deines Modells.",
    checklistTitle: 'Implementierungs-Checkliste',
    minimalPatternTitle: 'Minimales Implementierungsmuster',
    minimalPatternDesc: 'Die genaue API unterscheidet sich je nach Anbieter, aber die Prompt-Struktur sollte so aussehen: stabiler Kontext zuerst, Cache-Grenze um das wiederverwendbare Präfix, aufgabenspezifische Eingabe zuletzt.',
    rememberTitle: 'Was du dir merken solltest',
    rememberDesc: 'Prompt-Caching ist eine Inferenz-Optimierung für wiederholte Präfixe. Es funktioniert am besten, wenn der Prompt-Aufbau langweilig und deterministisch ist. Setze die wiederverwendbare Masse an den Anfang, halte sie stabil, verschiebe verrauschte Daten nach hinten und vertraue nur den gemessenen Cache-Hit-Feldern.',
