    // MoE Offloading Guide
    moeOffloadTitle: 'Smartes Offloading für MoE-Modelle',
    moeOffloadDesc: 'Mixture-of-Experts-Modelle sind einzigartig geeignet für Offloading, weil nur ein Bruchteil der Experten pro Token aktiviert wird. So holst du das Maximum raus:',
    moeStrategy1Title: 'Den Hot Path im VRAM behalten',
    moeStrategy1Desc: 'Attention-Layer, das Router/Gate-Netzwerk und Shared Layers werden für jeden Token benötigt. Die müssen im VRAM bleiben. In llama.cpp nutze --ngl um zu steuern wie viele Layer auf der GPU liegen.',
    moeStrategy2Title: 'Inaktive Experten in CPU-RAM auslagern',
    moeStrategy2Desc: "Expert-Routing ändert sich pro Token. Derzeit inaktive Gewichte können später gebraucht werden. Experten auf der CPU reduzieren den VRAM-Bedarf, benötigen aber CPU-Rechnung oder Transfers. Das ist nicht kostenlos.",
    moeStrategy3Title: 'Expert-Prefetching nutzen',
    moeStrategy3Desc: "llama.cpp bietet --cpu-moe und --n-cpu-moe für Expertengewichte auf der CPU sowie --gpu-layers für die Schichtplatzierung. --override-kv verändert Modellmetadaten. Es aktiviert keine Expertenvorhersage oder Vorabladen.",
    moeStrategy4Title: 'Beispiel: Qwen3.5-35B-A3B bei Q4',
    moeStrategy4Desc: "Wenige aktive Parameter garantieren kein schnelles Offloading. Prüfe sämtliche Expertengewichte, gemeinsame Schichten, Attention-Zustand und die Gerätegrenze. Miss dann die vollständige Runtime.",
    moeKeyInsight: 'Kernaussage',
    moeKeyInsightText: "Verfügbarer Speicher begrenzt die Platzierung dichter Modelle und von MoE-Modellen. Der Durchsatz hängt zusätzlich von den Operationen und Transfers pro erzeugtem Token ab.",

    linkQuant: 'Erfahre, wie Quantisierung die Modellgröße bei minimalem Qualitätsverlust reduziert.',
    linkLocal: 'Vollständiger Leitfaden zum Ausführen von Modellen auf eigener Hardware.',
